TLM.f("Tempora/Pasc5-1",{"officium":"Feria Secunda in Rogationibus","rule":["no Gloria","no Credo","Suffr=Maria3;Ecclesiæ,Papa;;"],"ruleInherited":["Gloria","Credo","Suffr=Maria3;Ecclesiæ,Papa;;"],"fallback":"Tempora/Pasc5-0","sections":{"Introitus":[{"k":"ref","la":"Ps 17:7"},{"k":"text","la":"Exaudívit de templo sancto suo vocem meam, allelúja: et clamor meus in conspectu ejus, introívit in aures ejus, allelúja, allelúja."},{"k":"ref","la":"Ps 17:2-3"},{"k":"text","la":"Díligam te, Dómine, virtus mea: Dóminus firmaméntum meum et refúgium meum et liberátor meus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Exaudívit de templo sancto suo vocem meam, allelúja: et clamor meus in conspectu ejus, introívit in aures ejus, allelúja, allelúja."}],"Oratio":[{"k":"text","la":"Præsta, quǽsumus, omnípotens Deus: ut, qui in afflictióne nostra de tua pietáte confídimus; contra advérsa ómnia, tua semper protectióne muniámur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Jacóbi Apóstoli."},{"k":"ref","la":"Jas 5:16-20"},{"k":"text","la":"Caríssimi: Confitémini altérutrum peccáta vestra, et oráte pro ínvicem, ut salvémini: multum enim valet deprecátio justi assídua. Elías homo erat símilis nobis passíbilis: et oratióne orávit, ut non plúeret super terram, et non pluit annos tres et menses sex. Et rursum orávit: et cœlum dedit plúviam et terra dedit fructum suum. Fratres mei, si quis ex vobis erráverit a veritáte et convérterit quis eum: scire debet, quóniam, qui convérti fécerit peccatórem ab erróre viæ suæ, salvábit ánimam ejus a morte, et opériet multitúdinem peccatórum."}],"Graduale":[{"k":"text","la":"Allelúja."},{"k":"ref","la":"Ps 117:1"},{"k":"text","la":"Confitémini Dómino, quóniam bonus: quóniam in sǽculum misericórdia ejus."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam."},{"k":"ref","la":"Luc 11:5-13"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Quis vestrum habébit amícum, et íbit ad illum média nocte, et dicet illi: Amíce, cómmoda mihi tres panes, quóniam amícus meus venit de via ad me, et non hábeo quod ponam ante illum: et ille deíntus respóndens, dicat: Noli mihi moléstus esse, jam óstium clausum est, et púeri mei mecum sunt in cubíli, non possum súrgere et dare tibi. Et si ille perseveráverit pulsans: dico vobis, etsi non dabit illi surgens, eo quod amícus ejus sit, propter improbitátem tamen ejus surget et dabit illi, quotquot habet necessários. Et ego dico vobis: Pétite, et dábitur vobis: quǽrite, et inveniétis: pulsáte, et aperiétur vobis. Omnis enim, qui petit, áccipit: et qui quærit, invénit: et pulsánti aperietur, Quis autem ex vobis patrem pétii panem, numquid lápidem dabit illi? Aut piscem: numquid pro pisce serpéntem dabit illi? Aut si petíerit ovum: numquid pórriget illi scorpiónem? Si ergo vos, cum sitis mali, nostis bona data dare fíliis vestris: quanto magis Pater vester de cœlo dabit spíritum bonum peténtibus se?"}],"Offertorium":[{"k":"ref","la":"Ps 108:30-31"},{"k":"text","la":"Confitébor Dómino nimis in ore meo: et in médio multórum laudábo eum, qui ástitit a dextris páuperis: ut salvam fáceret a persequéntibus ánimam meam, allelúja."}],"Secreta":[{"k":"text","la":"Hæc múnera, quǽsumus, Dómine, et víncula nostræ pravitátis absólvant, et tuæ nobis misericórdiæ dona concílient."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Luc 11:9-10"},{"k":"text","la":"Pétite, et accipiétis: quǽrite, et inveniétis: pulsáte, et aperiétur vobis: omnis enim qui pétit, áccipit: et qui quærit, ínvenit: et pulsánti aperiétur, allelúja."}],"Postcommunio":[{"k":"text","la":"Vota nostra, quǽsumus, Dómine, pio favóre proséquere: ut, dum dona tua in tribulatióne percípimus, de consolatióne nostra in tuo amóre crescámus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"7edc7d3631da9012":{"t":"<i>Pomolimo se</i>.\nPodaj, molimo, svemogući Bože, da se u svojoj tjeskobi uzdamo u tvoju blagost te nas tvoja zaštita uvijek obrani od svih protivnosti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj, molimo, svemogući Bože, da se u tjeskobi svojoj uzdam-o u Tvoju blagost, te nas Tvoja zaštita uvijek obrani od svih protivnosti, po G. n.","knRef":"Kniewald 1942, str. 330–331 (snimka 166) (OCR)"},"027274c3a2aff9a7":{"t":"Ovi prinosi, Gospodine, razriješili okove naše zlobe i donijeli nam darove tvojega milosrđa.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Ovi prinosi, Gospodine, razriješili okove naše zlobe i priklonili nam darove Tvojega milosrđa, po . G. o.","knRef":"Kniewald 1942, str. 330–331 (snimka 166) (OCR)"},"bc95a634d1101d12":{"t":"<i>Pomolimo se</i>.\nMolimo te, Gospodine, prati naše želje milom prijaznošću, da porastemo u tvojoj ljubavi dok u nevolji primamo tvoje darove.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo Te, Gospodine, prati naše zavjete milom prijaznošću, da porastemo u Tvojoj ljubavi, dok u nevolji primamo Tvoje darove, po G. n.","knRef":"Kniewald 1942, str. 330–331 (snimka 166) (OCR)"},"f188987709ca7e4f":{"t":"Ps 17, 7, Ps 17, 2-3\n(Ps 17, 7) Uslišao je iz svoga svetoga hrama glas moj. I vapaj je moj dopro do uha njegova, <i>aleluja</i>, <i>aleluja</i>.\n(Ps 17, 2-3) Ljubit ću te, Gospodine, jakosti moja. Gospodin je moja tvrđa, moje utočište i moj osloboditelj.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 17, 7) Uslišao je iz svoga svetoga hrama glas moj. I vapaj je moj dopro do uha njegova, <i>aleluja</i>, <i>aleluja</i>.","v":"∅ → aleluia; ∅ → aleluia","kn":"(Ps. 17, 7). Uslišao je iz hrama svoga svetoga glas moj, aleluja; i vapaj je moj dopro do uha nj«- gova, aleluja, aleluja. (Ps. 17, 2) Ljubim Te, Gospodine, kreposti moja; Gospodin je tvrđava moja i utočište moje i izbavitelj moj. Slava Ocu . . . Uslišao je . . .","knRef":"Kniewald 1942, str. 328–329 (snimka 165) (OCR)"},"82130abd91903c4a":{"t":"Jk 5, 16-20\nČitanje Poslanice bl. Jakova apostola. Predragi! Ispovijedajte svoje grijehe jedan drugome i molite jedan za drugoga, da se spasite, jer mnogo može ustrajna molitva pravednika. Ilija je bio čovjek iste naravi kao i mi i vruće je molio da ne pada kiša. I nije padala na zemlju kiša tri godine i šest mjeseci. I opet je molio Boga i nebo je dalo kišu a zemlja je dala svoj plod. – Braćo! Ako tko među vama zastrani s pravog puta i netko ga obrati neka zna, da koji obrati grješnika s njegova krivoga puta, taj će spasiti njegovu dušu od smrti i pokriti množinu grijeha.","kn":"Čitanje poslanice bi. Jakova apostola (5, 16-20). Predragi! Ispovijedajte svoje grijehe jedan drugomu i molite jedan za drugoga, da se spasite, jer mnogo može ustrajna molitva pravednika. Ilija je bio čovjek iste naravi kao i ml, i vruće je molio, da ne pada kiša. I nije padala na zemlju kiša tri godine i šest mjeseci. I opet je molio Boga, i nebo je dalo kišu, a zemlja je dala svoj plod. Braćo! Ako tko među vama zastrani s pravoga puta i netko ga obrati, neka zna, da koji obrati grješnlika s njegova krivoga puta, taj će spasiti njegovu dušu od smrti i pokriti množinu grijeha.","knRef":"Kniewald 1942, str. 330–331 (snimka 166) (OCR)"},"99701d8a4e1d45f9":{"t":"Ps 106, 1\n<i>Aleluja</i>.\nslavite Gospodina jer je dobar, jer je do vijeka milosrđe njegovo.","kn":"Aleluja. Aleluja. Aleluja. (Ps.- 117, 1). Hvalite Gospodina, jer je dobar, jer je do vijeka milosrđe njegovo.","knRef":"Kniewald 1942, str. 296–297 (snimka 149) (OCR)"},"c95b18caa38840e7":{"t":"Lk 11, 5-13\nSlijedi sveto Evanđelje po Luki. U ono vrijeme reče Isus svojim učenicima: Tko od vas ima prijatelja i pođe k njemu u ponoći i reče mu: Prijatelju, uzajmi mi tri kruha, jer mi je prijatelj došao s puta i nemam što da metnem pred njega, a on da iznutra odgovori: Ne dosađuj mi! Vrata su već zatvorena, moja su djeca sa mnom u sobi, ne mogu ustati da ti dam! Ali ako on ustraje kucati, kažem vam, ako i ne ustane da mu dade zato što mu je prijatelj, ustat će radi njegova navaljivanja i dat će mu koliko god treba. I ja vama kažem: Molite i dat će vam se, tražite i naći ćete, kucajte i otvorit će vam se. Jer svaki koji moli dobiva, koji traži nalazi, i koji kuca otvara mu se. Ako tko od vas zamoli u oca kruha, zar će mu dati kamen? Ili ribu, zar će mu mjesto ribe dati zmiju? Ili ako zamoli jaje, zar će mu dati štipavca? Kad dakle vi, koji ste zli, znate djecu obdariti dobrim darovima, koliko će više dobra duha dati vaš nebeski Otac onima koji ga mole.","kn":"t Slijedi sveto evanđelje po Luki (11, 5-13). U ono vrijeme reče Isus svojim učenicima: Tko od vas ima prijatelja i pođe k njemu u ponoći i reče mu: Prijatelju, uzajmi mi tri kruha, jer mi je prijatelj došao s puta i nemam, što da metnem pred njega, a on da iznutra odgovori: Ne dosadu j mi: vrata su već zatvorena, moja su djeca sa mnom u sobi, ne mogu ustati, da ti dam. Ali ako on ustraje kucati, kažem vam, ako i ne ustane da mu dade zato, što mu je prijatelj, ustat će radi njegova navaljivanja i dat će mu, kolikogod treba. I ja vama kažem: Molite, i dat će vam se, tražite, i naći ćete, kucajte i otvorit će vam se. Jer svaki, koji moli, dobiva, koji traži, nalazi, 1 koji kuca, otvara mu se. Ako tko od vas zamoli oca kruha, zar će mu dati kamen? Ili ribu, zar će mu mjesto ribe dati zmiju? Ili ako zamoli jaje, zar će mu dati štipavca? Kad dakle vi, koji ste zli, znate svoju djecu obdariti dobrim darovima, kolikcf' će više dobra duha dati vaš nebeski Otac onima, koji ga mole.","knRef":"Kniewald 1942, str. 330–331 (snimka 166) (OCR)"},"c71405cffe412a24":{"t":"Ps 108, 30-31\nMnogo ću hvaliti Gospodina ustima svojim i usred mnoštva slavit ću ga, jer stade s desne strane ubogome, da bi spasio dušu moju od onih koji je progone. <i>Aleluja</i>.","kn":"(Ps. 108, 30, 31). Hvalit ću Gospodina veoma ustima svojim i usred mnogih slavit ću ga, jer stade s desne strane ubogomu, da bi spasao dušu moju od onih, koji je gone. Aleluja.","knRef":"Kniewald 1942, str. 330–331 (snimka 166) (OCR)"},"1a0a565aa39e4fe3":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno da tebe, Gospodine, u svako doba, a osobito <i>u ovo</i> svečanije slavimo, kad je Krist žrtvovan, naše vazmeno Janje. On je naime pravo janje koje oduze grijehe svijeta. Svojom smrću on je uništio našu smrt i svojim uskrsnućem obnovio naš život. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"j Uistinu je dostojno i pravedno, pravo i spaso- I doba, ali osobito svečano na - današnji dan, (u ovo vrijeme), kad je žrtvovano naše vazmeno Janje, I Isukrst; jer On je pravo janje, koje je uzelo grijehe : svojim je uskrsnućem obnovio naš ž^vot. Zato pje- I vamo pjesmu Tvoje slave s anđelima i s arkanđe lima, s. prijestolima i s gospodstvima i sa svom silom nebeske vojske govoreći bez prestanka:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"a4a37a0b4e71948e":{"t":"Luc 11, 9-10\nMolite i dat će vam se, tražite i naći ćete, kucajte i otvorit će vam se. Svaki koji moli prima, i koji traži nalazi, i koji kuca otvara mu se, <i>aleluja</i>.","kn":"(Lk. 11, 19, 10). Molite i dat će vam se; tražite i naći ćete, kucajte i otvorit će vam se; jer svaki, koji moli, prima, i koji traži, nalazi; i koji kuca, otvara mu se. Aleluja.","knRef":"Kniewald 1942, str. 330–331 (snimka 166) (OCR)"}}});
